package edu.uao.yugioh.controller; import edu.uao.yugioh.model.*; import edu.uao.yugioh.persistence.HistorialRepository; import edu.uao.yugioh.view.BatallaView; public class BatallaController { private final BatallaView view; private final Jugador j1,j2; private final HistorialRepository repo; private final CalculadoraCombate calculadora=new CalculadoraCombate(); public BatallaController(BatallaView v,Jugador a,Jugador b,HistorialRepository r){view=v;j1=a;j2=b;repo=r;} public void iniciar(){j1.agregarMonstruo(new Monstruo("Mago Oscuro",2500,2100));j1.agregarMonstruo(new Monstruo("Dragón Blanco",3000,2500));j2.agregarMonstruo(new Monstruo("Kuriboh",300,200));j2.agregarMonstruo(new Monstruo("Dragón Rojo",2400,2000));view.configurar(j1,j2,this::atacar);view.setVisible(true);} private void atacar(Monstruo atacante,Monstruo defensor){ResultadoCombate r=calculadora.atacar(atacante,defensor,j1,j2);repo.guardar(r);view.mostrarResultado(r,j1,j2);}}